import{_ as e,o as i,c as o,a2 as t}from"./chunks/framework.BsAvorgW.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1784136889000}'),s={name:"guide/faq.md"};function l(n,a,r,d,h,c){return i(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="返回-407" tabindex="-1">返回 407 <a class="header-anchor" href="#返回-407" aria-label="Permalink to &quot;返回 407&quot;">​</a></h2><p>检查代理用户名和密码是否正确、账号是否已启用。没有任何启用账号时也会返回 <code>407</code>。</p><h2 id="返回-403" tabindex="-1">返回 403 <a class="header-anchor" href="#返回-403" aria-label="Permalink to &quot;返回 403&quot;">​</a></h2><p>目标域名或目标端口不在白名单。进入 <strong>设置</strong> 检查“允许域名”和“允许端口”。</p><h2 id="返回-502" tabindex="-1">返回 502 <a class="header-anchor" href="#返回-502" aria-label="Permalink to &quot;返回 502&quot;">​</a></h2><p>通常表示没有可用节点、供应商提取失败，或者短效代理无法连接目标。打开 <strong>日志</strong> 查看具体原因。</p><h2 id="webui-无法打开" tabindex="-1">WebUI 无法打开 <a class="header-anchor" href="#webui-无法打开" aria-label="Permalink to &quot;WebUI 无法打开&quot;">​</a></h2><p>依次检查：</p><ol><li>SelenaProxy 进程或容器是否运行；</li><li><code>status.host</code> 是否监听 <code>0.0.0.0</code>；</li><li>防火墙是否放行 <code>17892</code>；</li><li>服务器安全组是否允许访问；</li><li>日志中是否有监听端口失败。</li></ol><h2 id="复制链接中的地址不对" tabindex="-1">复制链接中的地址不对 <a class="header-anchor" href="#复制链接中的地址不对" aria-label="Permalink to &quot;复制链接中的地址不对&quot;">​</a></h2><p>进入 <strong>设置</strong>，把“对外访问地址”改成调用方能够访问的服务器 IP 或域名。不要填写 <code>http://</code>、端口或路径。</p><h2 id="忘记管理员密码" tabindex="-1">忘记管理员密码 <a class="header-anchor" href="#忘记管理员密码" aria-label="Permalink to &quot;忘记管理员密码&quot;">​</a></h2><p>管理员凭据保存在运行数据目录的 SQLite 数据库中。目前没有网页重置入口。请先备份数据，再重新初始化运行目录。</p><h2 id="docker-修改本地-config-yaml-没生效" tabindex="-1">Docker 修改本地 config.yaml 没生效 <a class="header-anchor" href="#docker-修改本地-config-yaml-没生效" aria-label="Permalink to &quot;Docker 修改本地 config.yaml 没生效&quot;">​</a></h2><p>首次启动后，实际运行配置保存在 <code>selena-proxy-data</code> 卷中，并由 WebUI 修改。主机上的 <code>config.yaml</code> 主要用于首次创建数据卷配置。</p><h2 id="windows-编译提示-link-exe-not-found" tabindex="-1">Windows 编译提示 link.exe not found <a class="header-anchor" href="#windows-编译提示-link-exe-not-found" aria-label="Permalink to &quot;Windows 编译提示 link.exe not found&quot;">​</a></h2><p>安装 Visual Studio Build Tools 2022，并选择 <strong>使用 C++ 的桌面开发</strong>。安装后重新打开 PowerShell，再运行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cargo build </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">locked</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>',19)])])}const k=e(s,[["render",l]]);export{u as __pageData,k as default};
